/** 브리프 규칙 — 조후 줄·그릇/밭 갈림·표시금지 */
function 궁통병렬규칙줄() {
  return [
    '  **조후(궁통) 줄은 자평 희기와 섞어 점수 내지 말고 「밭」 층으로 따로 말할 것** — 대조표 줄 끝 「조후: …」(필요·꺼림·무관·방위·용신 손상·용신이 운에서 드러남)와 취운 판정(결이 살아남/눌림)은 다른 책의 눈이다. 한 해를 말할 때 「취운으로는 …, 밭으로는 필요 글자 丙이 와서 …」처럼 나란히 두고 합산하지 않는다.',
    '  **그릇·밭이 갈리는 자리** — 위에 「그릇(자평)은 …, 밭(궁통)은 …으로 읽힘 — 두 책이 갈리는 자리, 한쪽으로 단정하지 않음」 줄이 있으면 그 문장을 그대로 한 번 옮긴다. 두 책을 한 판정으로 합치지 않는다.',
    '  **원문 판정어가 표시금지인 조문은 「원문이 여명에 경계를 둔 배합」이라고만 쓰고 그 뜻을 추측해 쓰지 말 것.** 재료에 원문이 없는 조문의 원문을 지어 쓰지 않는다. 富·貴 두 축은 「재물의 축(富)」「자리의 축(貴)」으로만 — 상격·귀격·천격 같은 등급어는 쓰지 않는다.',
  ];
}

/** 궁통보감 재료 두 표 — 필요 글자 소재표, 필요 글자가 오는 해. 기본 브리프와 궁통 브리프가 함께 쓴다 */
function 궁통재료줄(r47, m, opt = {}) {
  const L = [];
  try {
    const { JIJANGGAN } = require('./jijanggan');
    const 자리 = [['년간', m.yeonGan], ['월간', m.wolGan], ['시간', m.siGan]].filter(x => x[1]);
    const 지 = [['년지', m.yeonJi], ['월지', m.wolJi], ['일지', m.ilJi], ['시지', m.siJi]].filter(x => x[1]);
    const 소재 = g => {
      const 곳 = 자리.filter(x => x[1] === g).map(x => x[0]);
      for (const [라벨, j] of 지) { const h = (JIJANGGAN[j] || []).find(x => x.gan === g); if (h) 곳.push(`${라벨} ${j}${h.wi === '정기' ? '의 본기' : ' 속'}`); }
      return 곳.length ? 곳.join('·') : '**원국에 없음**';
    };
    let 용 = (r47.용 || []).filter(g => g.length === 1);
    let 기 = (r47.기 || []).map(g => g.replace(/多$/, '')).filter(g => g.length === 1);
    if (!용.length && GU) { try { const k = GU.칸찾기(m.ilGan, m.wolJi); if (k) { 용 = [...k.용, ...k.보좌]; 기 = k.기; } } catch (e) {} }
    L.push('  [필요 글자 소재표 — 궁통보감의 실명표. 「있다/없다」는 반드시 이 표로만 말할 것]');
    용.forEach(g => L.push(`  - 필요 ${g}: ${소재(g)}`));
    기.forEach(g => L.push(`  - 꺼림 ${g}: ${소재(g)}`));
    const seun = require('./seun');
    const 올해 = 세운올해(opt);
    const 정기 = j => { const h = (JIJANGGAN[j] || []).find(x => x.wi === '정기'); return h ? h.gan : null; };
    const 속 = j => (JIJANGGAN[j] || []).map(x => x.gan);
    L.push(`  [필요 글자가 오는 해 — ${올해}년부터 열여섯 해. 궁통보감의 운 읽기: **원국에 없는 필요 글자가 운에서 오는 해가 볕 드는 해, 꺼리는 글자가 오는 해가 조심할 해**. 천간으로 오면 크고(★▼) 지지 본기로 오면 그 다음(☆▽), 지지 속에 숨어 오면 약하다]`);
    for (let y = 올해; y < 올해 + 16; y++) {
      const g = seun.연간지(y); const 표 = [];
      for (const 글 of 용) { if (g.천간 === 글) 표.push(`필요 ${글}이 천간으로 옴 ★`); else if (정기(g.지지) === 글) 표.push(`필요 ${글}이 지지 본기로 옴 ☆`); else if (속(g.지지).includes(글)) 표.push(`필요 ${글}이 지지 속에 숨어 옴`); }
      for (const 글 of 기) { if (g.천간 === 글) 표.push(`꺼리는 ${글}이 천간으로 옴 ▼`); else if (정기(g.지지) === 글) 표.push(`꺼리는 ${글}이 지지 본기로 옴 ▽`); }
      L.push(`  - ${y} ${g.간지}: ${표.length ? 표.join(', ') : '필요·꺼림 글자 없음 — 평이한 해'}`);
    }
  } catch (e) {}
  return L;
}
