    (r47.용 || []).forEach(g => L.push(`- 필요 ${g}: ${소재(g)}`));
    (r47.기 || []).forEach(g => { const gg = g.replace(/多$/, ''); if (gg.length === 1) L.push(`- 꺼림 ${gg}: ${소재(gg)}`); });
    // 필요 글자가 오는 해
