        for (const 글 of 용) { if (g.천간 === 글) 표.push(`필요 ${글}이 천간으로 옴 ★`); else if (정기(g.지지) === 글) 표.push(`필요 ${글}이 지지 본기로 옴 ☆`); else if (속(g.지지).includes(글)) 표.push(`필요 ${글}이 지지 속에 숨어 옴`); }
