/** 판정어 → {부, 귀}. 처음 맞는 낱말이 각 축을 정하고, 그 낱말이 null 로 둔 축은 다음 낱말이 채운다 */
function 축찾기(말) {
  const 축 = { 부: null, 귀: null };
  if (!말) return 축;
  let 남은 = 말;
  for (const [x, 부, 귀] of 축색인) {
    if (!남은.includes(x)) continue;
    if (축.부 === null && 부 !== null) 축.부 = 부;
    if (축.귀 === null && 귀 !== null) 축.귀 = 귀;
    남은 = 남은.split(x).join(' ');
    if (축.부 !== null && 축.귀 !== null) break;
  }
  return 축;
}
