    子: [{ 구절:'支成水局…丙丁全無，雖有戊制，貧乏到老，運至南方，稍有衣食', 방향:['南'], 뜻:'조건', 조건:'물국에 丙丁이 전혀 없는 배합', 줄:274 }],
