    酉: [
      { 구절:'或支成金局，戊己透干，壬透無火，名曰虎格，運行西北', 방향:['西','北'], 뜻:'조건', 조건:'금국에 戊己·壬이 드러나고 불이 없는 배합', 줄:1660 },
      { 구절:'六辛日逢戊子時，運喜西方，陰若朝陽，切忌丙丁離位', 방향:['西'], 뜻:'조건', 조건:'戊子시의 배합', 줄:1664 },
    ],
    子: [{ 구절:'或支見亥子丑，干出比劫，無丙、名潤下格…運喜西北', 방향:['西','北'], 뜻:'조건', 조건:'亥子丑에 비겁이 드러나고 丙이 없는 배합', 줄:1724 }],
