    午: [{ 구절:'金水會夏天，富貴永無邊，運行火土地，快樂似神仙', 방향:['南'], 뜻:'조건', 조건:'庚辛이 드러나고 壬癸가 있는 배합', 줄:2050 }],
    申: [{ 구절:'名死處逢生，弱中復強，即運行西北', 방향:['西','北'], 뜻:'좋음', 줄:2069 /* 「亦不死也」는 수명 낱말이라 뺌(8차) */ }],
