// ── 칸(용·보좌·기) 가져오기 — 새 API(칸 함수) 먼저, 없으면 옛 표 ─────────
function 칸찾기(일간, 월지) {
  let GJ = null; try { GJ = require('./gungtong_jomun'); } catch (e) {}
  const 정리 = (c, 출처) => {
    if (!c) return null;
    const 벗김 = g => String(g || '').replace(/多$/, '');
    const 용 = (c.용 || []).map(벗김).filter(g => g.length === 1);
    let 보좌 = (c.보좌 || []).map(벗김).filter(g => g.length === 1);
    let 주용 = 용;
    if (!Array.isArray(c.보좌)) { 주용 = 용.slice(0, 1); 보좌 = 용.slice(1); }   // 옛 표: 우선순위 배열 — 첫 글자만 용, 나머지는 보좌
    else if (보좌.length) 주용 = 용.filter(g => !보좌.includes(g));            // 용에 보좌 글자가 겹쳐 있으면 보좌 쪽으로
    const 기 = (Array.isArray(c.기) ? c.기 : []).map(벗김).filter(g => g.length === 1 && !주용.includes(g) && !보좌.includes(g));
    if (!주용.length) return null;                            // 용이 비어 있으면 이 출처는 아직 안 채워진 것 — 다음 출처로
    return { 용: 주용, 보좌, 기, 요지: typeof c.요지 === 'string' ? c.요지 : '', 출처 };
  };
  let k = null;
  // 단일 출처(2026-10-07 확정): gungtong.칸(일간,월지) → {용, 으뜸, 보좌, 기, 요지, 조문요지, 원문}
  try { const GT = require('./gungtong'); if (typeof GT.칸 === 'function') k = 정리(GT.칸(일간, 월지), 'gungtong.칸()'); } catch (e) { k = null; }
  if (!k && GJ && typeof GJ.칸 === 'function') { try { k = 정리(GJ.칸(일간, 월지), '칸()'); } catch (e) { k = null; } }
  if (!k && GJ && GJ.표 && GJ.표[일간] && GJ.표[일간][월지]) k = 정리(GJ.표[일간][월지], '표');
  if (!k && GJ && GJ[일간] && GJ[일간][월지]) k = 정리(GJ[일간][월지], '모듈');
  if (!k) { try { const GT = require('./gungtong'); const c = GT.표 && GT.표[일간] && GT.표[일간][월지]; if (c) k = 정리(c, 'gungtong'); } catch (e) {} }
  return k;
}

function 명식에서(ctx) {
  if (!ctx) return null;
  if (ctx.ilGan) return ctx;
  if (ctx.명식 && ctx.명식.ilGan) return ctx.명식;
  if (ctx.m && ctx.m.ilGan) return ctx.m;
  return null;
}

/**
 * 운의 글자가 이 달의 조후에 무엇을 하는가.
 * @param {string} 일간  @param {string} 월지
 * @param {{천간:string, 지지:string}} 운  대운·세운·월운 한 줄
 * @param {object} ctx  명식(m) 또는 interpret 결과(r) — 용신 손상·투출·삼합 판정에 원국이 필요하다. 없으면 글자 판정만
 */
function 조후운(일간, 월지, 운, ctx) {
  const 칸 = 칸찾기(일간, 월지);
  const m = 명식에서(ctx);
  const 운천간 = 운 && 운.천간, 운지지 = 운 && 운.지지;
  if (!칸 || !운천간 || !운지지) return { 해당없음: true, 요약: '', 원문: [] };

  const 역할 = g => 칸.용.includes(g) ? '용' : 칸.보좌.includes(g) ? '보좌' : 칸.기.includes(g) ? '기' : null;
  const 판정 = g => { const r = 역할(g); return r === '기' ? '꺼림' : r ? '필요' : '무관'; };
  const 필요글자 = [...new Set([...칸.용, ...칸.보좌])];   // 용·보좌에 같은 글자가 겹쳐 와도 한 번만

  // 원국
  const 원천간 = m ? [m.yeonGan, m.wolGan, m.siGan].filter(Boolean) : [];
  const 원지지 = m ? [m.yeonJi, m.wolJi, m.ilJi, m.siJi].filter(Boolean) : [];
  const 중정기 = [];
  for (const j of 원지지) for (const h of (JIJANGGAN[j] || [])) if (h.wi !== '여기') 중정기.push(h.gan);

  // ① 천간
  const 천 = { 글자: 운천간, 판정: 판정(운천간), 역할: 역할(운천간), 투출: false, 손상: [] };
  if (m && 필요글자.includes(운천간) && !원천간.includes(운천간) && 운천간 !== 일간 && 중정기.includes(운천간)) 천.투출 = true;
  if (m) for (const g of 필요글자) {
    if (!원천간.includes(g)) continue;                       // 드러난 용신만 다친다 — 숨은 글자는 운 천간이 못 만진다
    if (간합[운천간] === g) 천.손상.push({ 종류: '합', 글자: g, 상대: 운천간 });
    else if (극[오행[운천간]] === 오행[g]) 천.손상.push({ 종류: '극', 글자: g, 상대: 운천간 });
  }

  // ② 지지 — 정기, 그리고 원국과 이루는 삼합·방합
  const 정기 = (JIJANGGAN[운지지] || []).find(h => h.wi === '정기');
  const 본 = 정기 ? 정기.gan : null;
  const 지 = { 글자: 운지지, 정기: 본, 판정: 본 ? 판정(본) : '무관', 역할: 본 ? 역할(본) : null, 국: null };
  if (m) {
    for (const [오, 셋] of Object.entries(삼합)) {
      if (!셋.includes(운지지)) continue;
      const 원 = 원지지.filter(j => 셋.includes(j) && j !== 운지지);
      if (!원.length) continue;
      const 모두 = [운지지, ...원];
      if (!모두.some(j => 왕지.includes(j))) continue;          // 왕지 없는 두 글자는 국으로 안 센다
      지.국 = { 종류: '삼합', 오행: 오, 글자들: [...new Set(모두)], 가져오는글자: 필요글자.concat(칸.기).filter(g => 오행[g] === 오) };
    }
    if (!지.국) for (const [오, 셋] of Object.entries(방합)) {
      if (!셋.includes(운지지)) continue;
      const 원 = 원지지.filter(j => 셋.includes(j) && j !== 운지지);
      if (new Set([운지지, ...원]).size === 3)
        지.국 = { 종류: '방합', 오행: 오, 글자들: 셋.slice(), 가져오는글자: 필요글자.concat(칸.기).filter(g => 오행[g] === 오) };
    }
    if (지.국) {
      const 오는 = 지.국.가져오는글자;
      지.국.판정 = 오는.some(g => 칸.기.includes(g)) && !오는.some(g => 필요글자.includes(g)) ? '꺼림'
                 : 오는.some(g => 필요글자.includes(g)) ? '필요' : '무관';
    }
  }

  // ③ 계절 — 운 지지의 방위, 그 칸의 원문 방위 구절
  const 절 = 계절표[운지지];
  const 인용 = ((운원문[일간] || {})[월지] || []).filter(x => x.방향.includes(절.방향));
  const 계절 = { 지지: 운지지, 방향: 절.방향, 오행: 절.오행, 이름: 절.이름, 인용 };

  // ④ 요약 한 줄 — 「조후: 필요 丙 옴 / 꺼림 戊 옴 / 무관」
  const 토막 = [];
  if (천.판정 === '필요') 토막.push(`필요 ${운천간} 옴(${천.역할})${천.투출 ? ' — 용신이 운에서 드러남' : ''}`);
  else if (천.판정 === '꺼림') 토막.push(`꺼림 ${운천간} 옴`);
  else 토막.push(`${운천간} 무관`);
  for (const s of 천.손상) 토막.push(`용신 ${s.글자} 손상(${s.종류} — 운 ${s.상대})`);
  if (본) {
    if (지.판정 === '필요') 토막.push(`필요 ${본} 본기로 옴(${운지지})`);
    else if (지.판정 === '꺼림') 토막.push(`꺼림 ${본} 본기로 옴(${운지지})`);
    else 토막.push(`${운지지} 무관`);
  }
  if (지.국 && 지.국.판정 !== '무관') 토막.push(`${지.국.글자들.join('')} ${지.국.종류}(${지.국.오행}) → ${지.국.판정} ${지.국.가져오는글자.join('·')}`);
  const 짧은요약 = '조후: ' + [...토막, 계절.이름].join(' / ');
  토막.push(계절.이름 + (인용.length ? ` — 원문 「${인용[0].구절}」${인용[0].조건 ? `(조건부: ${인용[0].조건}에만 — 이 명식이 그 배합인지는 조문 판정을 따를 것)` : ''}` : ''));
  const 요약 = '조후: ' + 토막.join(' / ');

  return { 해당없음: false, 일간, 월지, 운: { 천간: 운천간, 지지: 운지지 }, 칸: { 용: 칸.용, 보좌: 칸.보좌, 기: 칸.기 },
           천간: 천, 지지: 지, 계절, 요약, 짧은요약, 원문: 인용.map(x => ({ 구절: x.구절, 뜻: x.뜻, 조건: x.조건 || null, 줄: x.줄 })) };
}

/** 운 목록(대운·세운·월운 어느 것이든 {천간,지지}를 가진 줄)에 요약을 붙여 돌려준다 */
function 운목록조후(일간, 월지, 목록, ctx) {
  return (목록 || []).map(u => ({ ...u, 조후: 조후운(일간, 월지, u, ctx) }));
}

// ── 표시금지 글자 — 여명 조문·품행 낙인의 원문은 어떤 출력에도 내지 않는다 (2026-10-07)
// 8차(2026-10-07): 질병(疾·瞽·損目·殘病·災病)·수명(夭·死·而亡 — 「死處逢生」「死金」은 격 이름·무딘 쇠라 제외) 낱말도 가린다 — 조문 모듈이 표시금지 플래그로 먼저 가리고, 이것은 haeseol 쪽 마지막 그물
const 표시금지식 = /淫賤|刑夫|剋子|長舌|不生長|賤|疾|瞽|損目|殘病|災病|夭|死(?!處逢生|金)|而亡/;
