  const 초 = x.초점해 ? x.해들.find(h => h.연도 === x.초점해) : null;
  const L = [];
  L.push('▶ 한 줄로 말하면');
  if (초) L.push(`${초.연도}년은 ${초.첫말}입니다.${x.글자이름 ? (초.옴.length ? ` ${x.일}${받침(x.일) ? '을' : '를'} 맡는 ${x.글자이름}가 그해에 옵니다.` : ` ${x.일}${받침(x.일) ? '을' : '를'} 맡는 ${x.글자이름}는 그해에 오지 않습니다.`) : ''}`);
  else if (x.글자이름) {
    if (x.좋은해.length) L.push(`${x.일}의 글자가 오고 흐름도 열리는 해는 ${해말(x.좋은해.slice(0, 4))}입니다.`);
    else if (x.글자해.length) L.push(`${x.일}의 글자가 오는 해는 ${해말(x.글자해.slice(0, 4))}입니다. 다만 그해 흐름은 ${x.해들.filter(h => x.글자해.slice(0, 4).includes(h.연도)).map(h => `${h.연도}년이 「${h.첫말}」`).join(', ')}라 서두르기보다 준비하는 쪽이 낫습니다.${x.열린해.length ? ` 흐름이 열리는 해는 ${해말(x.열린해.slice(0, 3))}입니다.` : ''}`);
    else L.push(`앞으로 열다섯 해 안에 ${x.일}의 글자가 직접 오는 해는 드뭅니다. 흐름이 열리는 해는 ${해말(x.열린해.slice(0, 3))}입니다.`);
  }
  else L.push(x.좋은해.length ? `흐름이 열리는 해는 ${해말(x.좋은해.slice(0, 4))}이고, 크게 조심할 해는 ${해말(x.조심해.slice(0, 3))}입니다.` : `앞으로 몇 해는 지키며 다지는 쪽입니다.`);
  L.push('');
  L.push('▶ 쉽게 풀어 보면');
  L.push(`이 명식의 중심 그림은 ${일간}입니다.${x.글자이름 ? ` 물으신 ${x.일}${받침(x.일) ? '은' : '는'} 이 명식에서 ${x.글자이름}가 맡습니다. 그 글자가 그해의 위 글자나 아래 글자로 들어오는 해에 그 일이 움직이기 쉽고, 그해 흐름이 열려 있으면 더 순하게 풀립니다.` : ''}`);
